var a=[{title:`Najpierw priorytet`,text:`Zmęczenie narasta w trakcie treningu, więc ruch najważniejszy dla Twojego celu zwykle trafia tam, gdzie możesz go wykonać dobrze. Ciężkie przysiady, wyciskania i trudne ciągnięcia często stoją na początku planów siłowych. Nowe, złożone umiejętności też lepiej wychodzą ze świeżą koncentracją i kontrolowaną praktyką. Unikaj zostawiania technicznie najtrudniejszego ćwiczenia na zakończenie, gdy jesteś najbardziej zmęczony.`},{title:`Ćwiczenia złożone i izolowane`,text:`Ruchy wielostawowe trenują kilka mięśni razem i mogą wymagać więcej koordynacji i wysiłku całego ciała niż uginanie ramion czy unoszenia. Popularna kolejność to rozgrzewka, główne ćwiczenia, ćwiczenia drugorzędne, izolowane i opcjonalna kondycja. To praktyczny zwyczaj, a niektóre treningi i niektórzy ludzie będą potrzebować innej kolejności.`},{title:`Co pokazują dowody`,text:`Najnowsze dowody ACSM pokazują, że wykonywanie ćwiczeń siłowych blisko początku treningu może poprawiać siłę w tych ruchach. Wzrost mięśni wydaje się mniej zależeć od kolejności ćwiczeń w wielu porównaniach. Jeśli Twoim głównym celem są lepsze podciągnięcia, rób je przed ćwiczeniami, które męczą ramiona i plecy, nawet jeśli oznacza to, że przysiady wypadną później.`},{title:`Core i kondycja`,text:`Ciężka deska lub noszenie tuż przed ciężkimi przysiadami może zmęczyć mięśnie, których potrzebujesz do stabilizacji przysiadu. Łatwa praca nad mobilnością i aktywacją może iść pierwsza, a cięższa praca nad core może lepiej pasować po głównych ćwiczeniach. Jeśli kondycja jest Twoim głównym celem, cardio może być głównym blokiem, a praca siłowa ułożona wokół niego.`},{title:`Przykład`,text:`40-minutowy trening siłowy mógłby wyglądać tak: pięciominutowa rozgrzewka, potem przysiady goblet jako główne ćwiczenie, wiosłowanie, wariant pompki, zawias i krótka seria desek bocznych. Trening z umiejętnością na pierwszym miejscu mógłby zamiast tego zacząć się od kontrolowanej progresji podciągania z masą własnego ciała, przed pozostałymi ćwiczeniami.`}];var o=[{label:`Stanowisko ACSM z 2026 roku`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Wcześniejsze zasady ACSM dotyczące kolejności ćwiczeń`,url:`https://pubmed.ncbi.nlm.nih.gov/11828249/`}];var n={sections:a,sources:o};export{n as default,a as sections,o as sources};